def transform(grid):
    uniform = [
        i for i, row in enumerate(grid)
        if all(v == row[0] for v in row)
    ]
    # The separator's color is the uniform-row color that appears least
    # elsewhere; this avoids mistaking uniform rows in the 2-column data.
    sep = min(
        uniform,
        key=lambda i: sum(
            v == grid[i][0]
            for j, row in enumerate(grid) if j != i
            for v in row
        )
    )

    top, bottom = grid[:sep], grid[sep + 1:]
    top_counts, bottom_counts = {}, {}
    for rows, counts in ((top, top_counts), (bottom, bottom_counts)):
        for row in rows:
            for v in row:
                counts[v] = counts.get(v, 0) + 1

    common = set(top_counts) & set(bottom_counts)
    bg = max(common, key=lambda v: top_counts[v] + bottom_counts[v])

    return [
        [3 if a == b else bg for a, b in zip(r1, r2)]
        for r1, r2 in zip(top, bottom)
    ]
